<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue';

type Page = 'inbox' | 'temporary' | 'accounts' | 'settings';
type Mailbox = { id:string; address:string; provider?:'native'|'temp_mail_io'; status:'active'|'expired'|'deleting'; createdAt:number; expiresAt:number };
type Email = { id:string; mailboxId:string|null; fromAddress:string; subject:string; snippet:string; receivedAt:number; localIsRead:number; source:string;sourceFolder?:string|null };
type Detail = Email & { text:string; otpCandidates:string[]; bodyTruncated:boolean; hasHtml:boolean; attachments:Array<{id:string;filename:string;size:number;skippedReason:string|null}> };
type Account = { id:string;provider:string;connectionType:string;emailAddress:string;authStatus:string;syncStatus:string;syncError?:string|null;imapProvider?:string;folders?:string[]|string };
type ImapFolder = { name:string;flags:string[] };
type SourceCategory = 'all'|'gmail'|'outlook'|'qq'|'other'|'temporary';
type InboxSource = {key:string;label:string;category:Exclude<SourceCategory,'all'>;kind:'folder'|'provider'|'temporary';folder?:string;accountId?:string;mailboxId?:string;hubInbox?:boolean};
type GmailSetup = {configured:boolean;missingSecrets:string[];redirectUri:string|null};
const pages: {id:Page;label:string;icon:string}[]=[{id:'inbox',label:'统一收件箱',icon:'▤'},{id:'temporary',label:'临时邮箱',icon:'◷'},{id:'accounts',label:'邮箱连接',icon:'⊞'},{id:'settings',label:'偏好设置',icon:'⚙'}];
const sourceCategories:{id:SourceCategory;label:string;icon:string}[]=[{id:'all',label:'全部',icon:'▤'},{id:'gmail',label:'Gmail',icon:'G'},{id:'outlook',label:'Outlook',icon:'O'},{id:'qq',label:'QQ 邮箱',icon:'Q'},{id:'other',label:'其他',icon:'＋'},{id:'temporary',label:'临时邮箱',icon:'◷'}];
const page=ref<Page>('inbox'), mailboxes=ref<Mailbox[]>([]), emails=ref<Email[]>([]), selectedMailbox=ref(''), selectedEmail=ref<Detail|null>(null), accounts=ref<Account[]>([]),gmailSetup=ref<GmailSetup>({configured:false,missingSecrets:[],redirectUri:null});
const busy=ref(false), loading=ref(true), error=ref(''), notice=ref(''), health=ref('checking');
const search=ref(''), activeCategory=ref<SourceCategory>('all'),selectedSourceKey=ref('all'),unreadFilter=ref('all'), nextCursor=ref<string|null>(null), loadingMore=ref(false);
const showOtp=ref(false), bodyMode=ref<'text'|'html'>('text');
const preferences=ref({ttl:60,refreshSeconds:20,maskOtp:true,theme:'light'});
const forwardedSettings=ref({provider:'qq',emailAddress:'',appPassword:'',folders:'INBOX'});
const availableImapFolders=ref<ImapFolder[]>([]),selectedImapFolders=ref<string[]>([]);
const showImapSetup=ref(false);
const tempMailDomains=ref<string[]>([]),tempMailDomain=ref(''),tempMailName=ref(''),tempMailDomainsLoading=ref(false),showTempMailCustomForm=ref(false);
const visibleEmails=computed(()=>selectedMailbox.value?emails.value.filter(e=>e.mailboxId===selectedMailbox.value):emails.value);
const unreadCount=computed(()=>visibleEmails.value.filter(e=>!e.localIsRead).length);
const unreadTotal=computed(()=>emails.value.filter(e=>!e.localIsRead).length);
const activeMailboxes=computed(()=>mailboxes.value.filter(box=>box.status==='active').length);
const forwardingFolders=computed(()=>{const account=accounts.value.find(item=>item.connectionType==='forwarded_imap'&&item.authStatus==='connected');if(!account?.folders)return[];try{const folders=Array.isArray(account.folders)?account.folders:JSON.parse(account.folders);return Array.isArray(folders)?folders.filter((folder):folder is string=>typeof folder==='string'&&folder.toLowerCase()!=='inbox'):[];}catch{return[];}});
function emailCategory(address:string):Exclude<SourceCategory,'all'|'temporary'>{const domain=address.toLowerCase().split('@').pop()??'';if(['gmail.com','googlemail.com'].includes(domain))return'gmail';if(['outlook.com','hotmail.com','live.com','msn.com'].includes(domain))return'outlook';if(['qq.com','foxmail.com'].includes(domain))return'qq';return'other';}
function sourceLabel(folder:string){return folder.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i)?.[0]??folder;}
function extractMailLinks(text:string){return [...new Set(text.match(/https?:\/\/[^\s"'<>]+/g)??[])].slice(0,8);}
const inboxSources=computed<InboxSource[]>(()=>[
  ...accounts.value.filter(account=>account.connectionType==='forwarded_imap'&&account.authStatus==='connected').map(account=>({key:`hub-inbox:${account.id}`,label:account.emailAddress,category:emailCategory(account.emailAddress),kind:'folder' as const,folder:'INBOX',accountId:account.id,hubInbox:true})),
  ...forwardingFolders.value.map(folder=>({key:`folder:${folder}`,label:sourceLabel(folder),category:emailCategory(sourceLabel(folder)),kind:'folder' as const,folder})),
  ...accounts.value.filter(account=>account.connectionType!=='forwarded_imap'&&account.authStatus==='connected').map(account=>({key:`provider:${account.id}`,label:account.emailAddress,category:emailCategory(account.emailAddress),kind:'provider' as const,accountId:account.id})),
  ...mailboxes.value.map(box=>({key:`temporary:${box.id}`,label:box.address,category:'temporary' as const,kind:'temporary' as const,mailboxId:box.id})),
]);
const categorySources=computed(()=>activeCategory.value==='all'?inboxSources.value:inboxSources.value.filter(source=>source.category===activeCategory.value));
const selectedSource=computed(()=>inboxSources.value.find(source=>source.key===selectedSourceKey.value)??null);
function categoryLabel(category:SourceCategory){return sourceCategories.find(item=>item.id===category)?.label??'邮箱';}
function categoryCount(category:SourceCategory){return category==='all'?inboxSources.value.length:inboxSources.value.filter(source=>source.category===category).length;}
let refreshTimer:number|undefined, searchTimer:number|undefined, inboxRequestId=0;
async function api<T>(path:string, init:RequestInit={}):Promise<T>{const headers=new Headers(init.headers);if(init.body)headers.set('Content-Type','application/json');const response=await fetch(path,{...init,headers});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data?.error?.message??`请求失败 (${response.status})`);return data as T;}
function emailListUrl(cursor?:string){const params=new URLSearchParams({limit:'10'});const source=selectedSource.value;if(source?.kind==='folder'){params.set('source','forwarded');params.set('folder',source.folder!);}else if(source?.kind==='provider')params.set('accountId',source.accountId!);else if(source?.kind==='temporary')params.set('mailboxId',source.mailboxId!);if(unreadFilter.value!=='all')params.set('unread',unreadFilter.value);if(search.value.trim())params.set('q',search.value.trim());if(cursor)params.set('cursor',cursor);return `/api/v1/emails?${params}`;}
async function reload(){const requestId=++inboxRequestId;loadingMore.value=false;error.value='';try{const [m,a,g]=await Promise.all([api<{mailboxes:Mailbox[]}>('/api/v1/mailboxes'),api<{accounts:Account[]}>('/api/v1/accounts'),api<GmailSetup>('/api/v1/accounts/gmail/status')]);if(requestId!==inboxRequestId)return;mailboxes.value=m.mailboxes;accounts.value=a.accounts;gmailSetup.value=g;const forwarded=a.accounts.find(account=>account.connectionType==='forwarded_imap');if(forwarded){forwardedSettings.value.emailAddress=forwarded.emailAddress;forwardedSettings.value.provider=forwarded.imapProvider??'qq';if(forwarded.folders){try{const folders=Array.isArray(forwarded.folders)?forwarded.folders:JSON.parse(forwarded.folders);if(Array.isArray(folders)){forwardedSettings.value.folders=folders.join('\n');selectedImapFolders.value=folders;}}catch{/* Keep the default folder when the saved folder list is malformed. */}}}else showImapSetup.value=true;if(selectedSourceKey.value.startsWith('empty:')){emails.value=[];nextCursor.value=null;health.value='ready';return;}const e=await api<{emails:Email[];nextCursor:string|null}>(emailListUrl());if(requestId!==inboxRequestId)return;emails.value=e.emails;nextCursor.value=e.nextCursor;health.value='ready';}catch(e){if(requestId!==inboxRequestId)return;health.value='error';error.value=e instanceof Error?e.message:'无法连接服务';}finally{if(requestId===inboxRequestId)loading.value=false;}}
async function loadMore(){if(!nextCursor.value||loadingMore.value)return;const requestId=++inboxRequestId;loadingMore.value=true;error.value='';try{const result=await api<{emails:Email[];nextCursor:string|null}>(emailListUrl(nextCursor.value));if(requestId!==inboxRequestId)return;emails.value=[...emails.value,...result.emails];nextCursor.value=result.nextCursor;}catch(e){if(requestId===inboxRequestId)error.value=e instanceof Error?e.message:'无法读取更多邮件';}finally{if(requestId===inboxRequestId)loadingMore.value=false;}}
function searchChanged(){if(searchTimer)clearTimeout(searchTimer);searchTimer=window.setTimeout(()=>void reload(),300);}
function filtersChanged(){void reload();}
function go(next:Page){page.value=next;selectedEmail.value=null;if(next==='inbox')void reload();if(next==='temporary')void loadTempMailDomains();}
async function loadTempMailDomains(){if(tempMailDomainsLoading.value)return;tempMailDomainsLoading.value=true;try{const result=await api<{domains:string[]}>('/api/v1/temp-mail/domains');tempMailDomains.value=result.domains;if(!tempMailDomain.value)tempMailDomain.value=result.domains[0]??'';}catch(e){error.value=e instanceof Error?e.message:'无法加载临时邮箱域名';}finally{tempMailDomainsLoading.value=false;}}
async function createTempMailIoMailbox(custom=false){if(custom&&(!tempMailName.value.trim()||!tempMailDomain.value)){error.value='请填写自定义名称并选择域名';return;}busy.value=true;error.value='';notice.value='';try{const body={provider:'temp_mail_io',ttlMinutes:preferences.value.ttl,...(custom?{name:tempMailName.value.trim(),domain:tempMailDomain.value}:{})};const result=await api<{mailbox:Mailbox}>('/api/v1/mailboxes',{method:'POST',headers:{Origin:location.origin,'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify(body)});mailboxes.value=[result.mailbox,...mailboxes.value.filter(item=>item.id!==result.mailbox.id)];notice.value=`已创建 ${result.mailbox.address}，邮件由 temp-mail.io 接收`;}catch(e){error.value=e instanceof Error?e.message:'外部临时邮箱创建失败';}finally{busy.value=false;}}
function viewMailbox(box:Mailbox){selectedMailbox.value=box.id;selectedEmail.value=null;activeCategory.value='temporary';selectedSourceKey.value=`temporary:${box.id}`;page.value='inbox';void reload();}
function selectCategory(category:SourceCategory){activeCategory.value=category;selectedEmail.value=null;selectedMailbox.value='';const match=category==='all'?null:inboxSources.value.find(source=>source.category===category);selectedSourceKey.value=match?.key??(category==='all'?'all':`empty:${category}`);emails.value=[];nextCursor.value=null;if(match||category==='all')void reload();else loading.value=false;}
function selectInboxSource(source:InboxSource|null){selectedSourceKey.value=source?.key??'all';activeCategory.value=source?.category??'all';selectedMailbox.value=source?.mailboxId??'';selectedEmail.value=null;void reload();}
async function createMailbox(){busy.value=true;error.value='';notice.value='';try{const result=await api<{mailbox:Mailbox}>('/api/v1/mailboxes',{method:'POST',headers:{Origin:location.origin,'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({ttlMinutes:preferences.value.ttl})});selectedMailbox.value=result.mailbox.id;activeCategory.value='temporary';selectedSourceKey.value=`temporary:${result.mailbox.id}`;page.value='inbox';await reload();notice.value='临时邮箱已创建';}catch(e){error.value=e instanceof Error?e.message:'创建失败';}finally{busy.value=false;}}
async function connectGmail(){busy.value=true;error.value='';try{const result=await api<{authorizationUrl:string}>('/api/v1/accounts/gmail/connect',{method:'POST',headers:{Origin:location.origin},body:'{}'});location.assign(result.authorizationUrl);}catch(e){error.value=e instanceof Error?e.message:'无法连接 Gmail';busy.value=false;}}
async function loadImapFolders(){busy.value=true;error.value='';try{const result=await api<{folders:ImapFolder[]}>('/api/v1/accounts/forwarded-imap/folders',{method:'POST',headers:{Origin:location.origin},body:JSON.stringify({provider:forwardedSettings.value.provider,emailAddress:forwardedSettings.value.emailAddress,appPassword:forwardedSettings.value.appPassword})});availableImapFolders.value=result.folders;selectedImapFolders.value=selectedImapFolders.value.filter(name=>result.folders.some(folder=>folder.name===name));notice.value=`连接成功，发现 ${result.folders.length} 个 IMAP 文件夹，请勾选要同步的文件夹`;}catch(e){error.value=e instanceof Error?e.message:'读取 IMAP 文件夹失败';}finally{busy.value=false;}}
async function saveForwardedSettings(){if(!selectedImapFolders.value.length){error.value='请先读取并至少勾选一个 IMAP 文件夹';return;}busy.value=true;error.value='';try{const result=await api<{account:Account}>('/api/v1/accounts/forwarded-imap',{method:'POST',headers:{Origin:location.origin},body:JSON.stringify({provider:forwardedSettings.value.provider,emailAddress:forwardedSettings.value.emailAddress,appPassword:forwardedSettings.value.appPassword,folders:selectedImapFolders.value})});forwardedSettings.value.appPassword='';showImapSetup.value=false;await reload();notice.value=`转发汇总邮箱已连接：${result.account.emailAddress}，首次同步任务已排队`;}catch(e){error.value=e instanceof Error?e.message:'无法连接汇总邮箱';}finally{busy.value=false;}}
async function syncGmail(account:Account){busy.value=true;error.value='';try{await api(`/api/v1/accounts/${account.id}/sync`,{method:'POST',headers:{Origin:location.origin}});notice.value='已开始获取该邮箱的最新邮件';await reload();}catch(e){error.value=e instanceof Error?e.message:'无法启动同步';}finally{busy.value=false;}}
async function refreshInbox(){busy.value=true;error.value='';notice.value='';try{const selected=selectedSource.value;let targets:Account[]=[];if(selected?.kind==='folder'){const account=accounts.value.find(item=>item.id===selected.accountId)||accounts.value.find(item=>item.connectionType==='forwarded_imap'&&item.authStatus==='connected');if(account)targets=[account];}else if(selected?.kind==='provider')targets=accounts.value.filter(account=>account.id===selected.accountId&&account.authStatus==='connected');else if(selected?.kind!=='temporary'&&!selectedSourceKey.value.startsWith('empty:'))targets=accounts.value.filter(account=>account.authStatus==='connected');if(targets.length){await Promise.all(targets.map(account=>api(`/api/v1/accounts/${account.id}/sync`,{method:'POST',headers:{Origin:location.origin}})));notice.value='同步已启动，正在获取最新邮件…';for(let attempt=0;attempt<20;attempt++){await new Promise(resolve=>setTimeout(resolve,1000));await reload();const current=targets.map(target=>accounts.value.find(account=>account.id===target.id));if(current.every(account=>account&&account.syncStatus!=='queued'&&account.syncStatus!=='syncing'))break;}const failed=targets.map(target=>accounts.value.find(account=>account.id===target.id)).find(account=>account&&['backoff','blocked'].includes(account.syncStatus));if(failed)throw new Error(`同步失败（${failed.syncError??failed.syncStatus}）。请到“邮箱连接”检查汇总邮箱与 IMAP 文件夹。`);const pending=targets.some(target=>['queued','syncing'].includes(accounts.value.find(account=>account.id===target.id)?.syncStatus??''));notice.value=pending?'同步仍在后台运行，稍后刷新即可看到邮件':'同步完成，已更新最近邮件。';}else{await reload();notice.value='邮件列表已刷新';}}catch(e){error.value=e instanceof Error?e.message:'获取邮件失败';}finally{busy.value=false;}}
async function renewMailbox(box:Mailbox){busy.value=true;error.value='';try{await api(`/api/v1/mailboxes/${box.id}/renew`,{method:'POST',headers:{Origin:location.origin},body:JSON.stringify({ttlMinutes:60})});await reload();notice.value='邮箱有效期已延长';}catch(e){error.value=e instanceof Error?e.message:'续期失败';}finally{busy.value=false;}}
async function deleteMailbox(box:Mailbox){busy.value=true;error.value='';try{await api(`/api/v1/mailboxes/${box.id}`,{method:'DELETE',headers:{Origin:location.origin}});selectedMailbox.value='';selectedEmail.value=null;await reload();notice.value='邮箱已停用，清理任务已排队';}catch(e){error.value=e instanceof Error?e.message:'删除失败';}finally{busy.value=false;}}
async function openEmail(item:Email){error.value='';try{const result=await api<{email:Detail}>(`/api/v1/emails/${item.id}`);selectedEmail.value=result.email;showOtp.value=!preferences.value.maskOtp;bodyMode.value='text';if(!item.localIsRead){await api(`/api/v1/emails/${item.id}`,{method:'PATCH',headers:{Origin:location.origin},body:JSON.stringify({localIsRead:true})});item.localIsRead=1;if(unreadFilter.value==='true')emails.value=emails.value.filter(email=>email.id!==item.id);}}catch(e){error.value=e instanceof Error?e.message:'无法打开邮件';}}
function copyValue(value:string){navigator.clipboard.writeText(value).then(()=>notice.value='内容已复制').catch(()=>error.value='复制失败，请手动复制');}
function expiry(value:number){const delta=Math.max(0,value-Date.now());if(delta===0)return'已过期';const mins=Math.ceil(delta/60000);return mins<60?`${mins} 分钟后过期`:`${Math.floor(mins/60)} 小时 ${mins%60} 分钟后过期`;}
function date(value:number){return new Date(value).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'});}
function savePreferences(){localStorage.setItem('mailhub-ui-preferences',JSON.stringify(preferences.value));updateRefreshTimer();notice.value='偏好设置已保存';}
function loadPreferences(){try{const stored=localStorage.getItem('mailhub-ui-preferences');if(stored)preferences.value={...preferences.value,...JSON.parse(stored)};}catch{/* Keep safe defaults when local settings are unreadable. */}}
function updateRefreshTimer(){if(refreshTimer)clearInterval(refreshTimer);refreshTimer=window.setInterval(()=>void reload(),preferences.value.refreshSeconds*1000);}
watch(()=>preferences.value.theme,value=>{document.documentElement.dataset.theme=value;});
onMounted(async()=>{loadPreferences();const result=new URLSearchParams(location.search).get('gmail');if(result){page.value='accounts';notice.value=result==='connected'?'Gmail 已连接，可以启动首次同步。':result==='cancelled'?'已取消 Gmail 授权。':'Gmail 授权未完成。';history.replaceState({},'',location.pathname);}await reload();updateRefreshTimer();});
onUnmounted(()=>{if(refreshTimer)clearInterval(refreshTimer);if(searchTimer)clearTimeout(searchTimer);});
</script>

<template>
  <div class="app-shell">
    <aside class="sidebar">
      <div class="brand-block"><div class="brand"><span class="brand-icon">✉</span><span>MailHub</span><small>BETA</small></div><div class="brand-sub">PERSONAL INBOX</div></div>
      <nav class="main-nav" aria-label="主导航"><button v-for="item in pages" :key="item.id" class="nav-item" :class="{active:page===item.id}" @click="go(item.id)"><span class="nav-icon">{{ item.icon }}</span>{{ item.label }}<small v-if="item.id==='inbox'&&unreadTotal">{{ unreadTotal }}</small></button></nav>
    </aside>
    <main class="main-area">
      <template v-if="page==='inbox'">
        <section class="page-title"><div><p class="eyebrow">UNIFIED INBOX</p><h1>统一收件箱</h1><p>按邮箱类型筛选来源，选择账号后查看该邮箱最新 10 封邮件。</p></div><button class="button primary" :disabled="busy" @click="refreshInbox">{{ busy?'正在获取邮件…':'↻ 获取最新邮件' }}</button></section>
        <nav class="source-categories" aria-label="邮箱分类"><button v-for="category in sourceCategories" :key="category.id" class="category-tab" :class="{active:activeCategory===category.id}" @click="selectCategory(category.id)"><span>{{ category.icon }}</span>{{ category.label }}<small>{{ categoryCount(category.id) }}</small></button></nav>
        <section class="inbox-workspace account-centric">
          <aside class="source-account-panel"><div class="source-panel-heading"><strong>{{ activeCategory==='all'?'邮箱账号':categoryLabel(activeCategory) }}</strong><span>{{ categorySources.length }}</span></div><button v-for="source in categorySources" :key="source.key" class="source-account-row" :class="{active:selectedSourceKey===source.key}" :title="source.kind==='folder'?source.folder:source.label" @click="selectInboxSource(source)"><span class="source-account-icon" :class="source.category">{{ source.category==='gmail'?'G':source.category==='outlook'?'O':source.category==='qq'?'Q':source.category==='temporary'?'◷':'＋' }}</span><span><strong>{{ source.label }}</strong><small>{{ source.hubInbox?'总邮箱收件箱':source.kind==='folder'?'QQ 中转文件夹':source.kind==='temporary'?'临时邮箱地址':categoryLabel(source.category)+' 邮箱' }}</small></span><i v-if="selectedSourceKey===source.key">›</i></button><div v-if="activeCategory!=='all'&&!categorySources.length" class="source-list-empty"><strong>暂无{{ categoryLabel(activeCategory) }}账号</strong><span>连接或转发对应邮箱后，会固定显示在这里。</span><button v-if="activeCategory!=='temporary'" class="text-button" @click="go('accounts')">前往邮箱连接</button></div></aside>
          <section class="source-mail-panel"><div class="source-mail-heading"><div><p>{{ selectedSource?.label??(activeCategory==='all'?'全部邮箱':categoryLabel(activeCategory)) }}</p><h2>{{ selectedEmail?'邮件详情':'最新邮件' }}</h2></div><span v-if="!selectedEmail" class="source-mail-count">{{ visibleEmails.length }} / 10 封</span><button v-else class="button small" @click="selectedEmail=null">‹ 返回邮件列表</button></div><div v-if="!selectedEmail" class="mail-list-tools"><label class="search-box"><span>⌕</span><input v-model="search" type="search" maxlength="120" placeholder="搜索主题、发件人…" aria-label="搜索主题或发件人" @input="searchChanged"></label><select v-model="unreadFilter" aria-label="按已读状态筛选" @change="filtersChanged"><option value="all">全部邮件</option><option value="true">仅未读</option><option value="false">已读</option></select></div><div v-if="!selectedEmail&&loading" class="empty-state">正在读取最新邮件…</div><div v-else-if="!selectedEmail&&!visibleEmails.length" class="empty-state"><b>✉</b><strong>{{ selectedSourceKey.startsWith('empty:')?'该分类还没有账号':activeCategory==='all'?'收件箱暂时为空':'这个邮箱暂时没有邮件' }}</strong><span>{{ activeCategory==='all'?'连接转发汇总邮箱后，邮件会自动归入统一收件箱。':'点击“获取最新邮件”从对应邮箱同步。' }}</span></div><button v-else-if="!selectedEmail" v-for="item in visibleEmails" :key="item.id" class="mail-preview-row" :class="{unread:!item.localIsRead}" @click="openEmail(item)"><span class="mail-preview-avatar">{{ (item.fromAddress||'?').slice(0,1).toUpperCase() }}</span><span class="mail-preview-main"><span class="mail-preview-top"><strong>{{ item.fromAddress||'未知发件人' }}</strong><time>{{ date(item.receivedAt) }}</time></span><strong class="mail-preview-subject">{{ item.subject||'（无主题）' }}</strong><span class="mail-preview-snippet">{{ item.snippet }}</span><span class="source-badge" :class="item.source">{{ item.source==='temporary'?'临时邮箱':item.sourceFolder?sourceLabel(item.sourceFolder):'Gmail' }}</span></span></button><article v-else class="message-view"><div class="sender"><span class="sender-avatar">{{ (selectedEmail.fromAddress||'?').slice(0,1).toUpperCase() }}</span><div><strong>{{ selectedEmail.fromAddress||'未知发件人' }}</strong><small>{{ selectedEmail.sourceFolder?sourceLabel(selectedEmail.sourceFolder):selectedEmail.source==='temporary'?'临时邮箱':'Gmail' }} · {{ date(selectedEmail.receivedAt) }}</small></div></div><h2>{{ selectedEmail.subject||'（无主题）' }}</h2><div v-if="selectedEmail.otpCandidates.length" class="otp-card"><div class="otp-heading"><div><strong>识别到的验证码</strong><small>候选值，请核对原文</small></div><button class="text-button" @click="showOtp=!showOtp">{{ showOtp?'隐藏':'显示' }}</button></div><div class="otp-values"><button v-for="otp in selectedEmail.otpCandidates" :key="otp" class="otp-code" @click="copyValue(otp)">{{ showOtp?otp:'••••••' }} <small>复制</small></button></div></div><div v-if="extractMailLinks(selectedEmail.text).length" class="extracted-mail-links"><strong>邮件中的链接</strong><a v-for="link in extractMailLinks(selectedEmail.text)" :key="link" :href="link" target="_blank" rel="noopener noreferrer" referrerpolicy="no-referrer">{{ link }}</a></div><p v-if="selectedEmail.bodyTruncated" class="truncated-note">正文超过显示上限，已截断。</p><div class="body-tabs"><button :class="{active:bodyMode==='text'}" @click="bodyMode='text'">纯文本</button><button :class="{active:bodyMode==='html'}" :disabled="!selectedEmail.hasHtml" @click="bodyMode='html'">隔离 HTML</button></div><div v-if="bodyMode==='text'" class="mail-body">{{ selectedEmail.text||selectedEmail.snippet||'此邮件没有纯文本正文。' }}</div><iframe v-else class="html-frame" :src="`/api/v1/emails/${selectedEmail.id}/html`" sandbox="" referrerpolicy="no-referrer" title="经过净化的邮件 HTML"></iframe><section v-if="selectedEmail.attachments.length" class="attachment-list"><h3>附件</h3><template v-for="item in selectedEmail.attachments" :key="item.id"><a v-if="!item.skippedReason" :href="`/api/v1/emails/${selectedEmail.id}/attachments/${item.id}`" class="attachment">↧ {{ item.filename }} <small>{{ Math.ceil(item.size/1024) }} KB</small></a><div v-else class="attachment skipped">{{ item.filename }} <small>未保存：{{ item.skippedReason }}</small></div></template><p>附件未经过病毒扫描，请谨慎打开。</p></section></article></section>
        </section><footer class="page-note">统一收件箱 · 邮件来源按已连接账号和中转文件夹归类</footer>
      </template>
      <template v-else-if="page==='temporary'">
        <section class="page-title"><div><p class="eyebrow">TEMPORARY ADDRESSES</p><h1>短暂的地址，完整的掌控。</h1><p>创建 MailHub 自有地址，或使用 temp-mail.io 的临时邮箱。</p></div></section>
        <div class="info-banner">MailHub 地址由本服务接收；temp-mail.io 地址由外部服务接收。临时地址到期后停止读取。</div>
        <section class="cards">
          <article class="card empty-card temp-mail-create-card">
            <div class="pill-icon">＋</div><h3>创建 temp-mail.io 邮箱</h3><p>随机地址可立即创建；也可以自定义名称和域名。</p>
            <button class="button primary" :disabled="busy" @click="createTempMailIoMailbox(false)">{{ busy?'正在创建…':'创建随机地址' }}</button>
            <button class="text-button" :disabled="busy" @click="showTempMailCustomForm=!showTempMailCustomForm;showTempMailCustomForm&&!tempMailDomains.length&&loadTempMailDomains()">{{ showTempMailCustomForm?'收起自定义地址':'自定义地址' }}</button>
            <div v-if="showTempMailCustomForm" class="temp-mail-custom-form">
              <label><span>自定义名称</span><input v-model="tempMailName" maxlength="31" autocomplete="off" placeholder="例如 my-account"></label>
              <label><span>域名</span><select v-model="tempMailDomain" :disabled="!tempMailDomains.length"><option v-for="domain in tempMailDomains" :key="domain" :value="domain">{{ domain }}</option></select></label>
              <button class="button small" :disabled="busy||!tempMailDomains.length" @click="createTempMailIoMailbox(true)">创建自定义地址</button>
              <button class="text-button" :disabled="tempMailDomainsLoading" @click="loadTempMailDomains">{{ tempMailDomainsLoading?'正在读取…':'刷新域名' }}</button>
              <small v-if="!tempMailDomains.length" class="temp-provider-note">{{ tempMailDomainsLoading?'正在读取可用域名…':'域名暂不可用，可稍后刷新；随机地址仍可尝试创建。' }}</small>
            </div>
          </article>
          <article v-for="box in mailboxes" :key="box.id" class="card mailbox-card"><div class="card-head"><span class="pill-icon">◷</span><span class="status-badge" :class="box.status">{{ box.status==='active'?'接收中':box.status==='deleting'?'清理中':'已到期' }}</span></div><div class="email-address">{{ box.address }}</div><div class="key-value"><span>邮箱服务</span><b>{{ box.provider==='temp_mail_io'?'temp-mail.io':'MailHub' }}</b></div><div class="progress"><i :style="{width:box.status==='active'?`${Math.max(0,Math.min(100,(box.expiresAt-Date.now())/(box.expiresAt-box.createdAt)*100))}%`:'0%'}"></i></div><div class="key-value"><span>剩余时间</span><b>{{ box.status==='active'?expiry(box.expiresAt):'不可读取' }}</b></div><div class="key-value"><span>到期时间</span><b>{{ date(box.expiresAt) }}</b></div><div class="key-value"><span>关联邮件</span><b>{{ emails.filter(email=>email.mailboxId===box.id).length }} 封（已加载）</b></div><div class="card-actions"><button class="button small" @click="copyValue(box.address)">复制地址</button><button class="button small" :disabled="box.status!=='active'" @click="viewMailbox(box)">查看邮件</button><button class="button small" :disabled="busy||box.status!=='active'" @click="renewMailbox(box)">延长 60 分钟</button><button class="button small danger" :disabled="busy||box.status==='deleting'" @click="deleteMailbox(box)">删除</button></div></article>
          <article v-if="!mailboxes.some(box=>box.provider!=='temp_mail_io')" class="card empty-card"><div class="pill-icon">＋</div><h3>还没有 MailHub 邮箱</h3><p>创建一个由 MailHub 自己接收邮件的私有地址。</p><button class="button primary" :disabled="busy" @click="createMailbox">创建 MailHub 邮箱</button></article>
        </section>
      </template>

      <template v-else-if="page==='accounts'"><section class="page-title"><div><p class="eyebrow">CONNECTED ACCOUNTS</p><h1>邮箱连接</h1><p>一个中转邮箱连接一次；来源文件夹会固定到统一收件箱。其他服务商可逐步扩展。</p></div></section><section v-if="!showImapSetup" class="card hub-connection-summary"><div><strong>转发汇总邮箱</strong><span>{{ accounts.find(account=>account.connectionType==='forwarded_imap')?.authStatus==='connected'?'已连接':'未连接' }} · {{ accounts.find(account=>account.connectionType==='forwarded_imap')?.emailAddress??'还没有配置' }}</span></div><button class="button small" @click="showImapSetup=true">{{ accounts.some(account=>account.connectionType==='forwarded_imap')?'管理文件夹与连接':'连接中转邮箱' }}</button></section><section v-if="showImapSetup" class="card imap-settings-card">
  <div class="card-head">
    <div><h2>转发汇总邮箱（IMAP）</h2><p>如果你已把几个邮箱转发到一个收件箱，在这里填写中转邮箱的 IMAP 账号。</p></div>
    <span class="status-badge" :class="accounts.some(account=>account.connectionType==='forwarded_imap'&&account.authStatus==='connected')?'active':''">{{ accounts.some(account=>account.connectionType==='forwarded_imap'&&account.authStatus==='connected')?'已连接':'未连接' }}</span>
  </div>
  <form @submit.prevent="saveForwardedSettings">
    <label class="setting-row"><span><strong>中转邮箱类型</strong><small>选择为转发邮件提供 IMAP 服务的邮箱。</small></span><select v-model="forwardedSettings.provider"><option value="qq">QQ 邮箱</option><option value="gmail">Gmail</option></select></label>
    <label class="setting-row"><span><strong>中转邮箱地址</strong><small>用于登录 IMAP 服务器。</small></span><input v-model="forwardedSettings.emailAddress" required type="email" autocomplete="username" placeholder="name@example.com"></label>
    <label class="setting-row"><span><strong>IMAP 授权码</strong><small>填写邮箱提供商生成的应用专用码，不是邮箱登录密码。更新配置时需要重新填写。</small></span><input v-model="forwardedSettings.appPassword" required type="password" autocomplete="new-password" placeholder="邮箱授权码"></label>
    <div class="folder-picker"><div class="folder-picker-head"><div><strong>同步文件夹</strong><small>先读取 QQ 邮箱实际的 IMAP 文件夹，再勾选存放转发邮件的文件夹。</small></div><button class="button small" type="button" :disabled="busy" @click="loadImapFolders">{{ busy?'正在连接…':'读取文件夹' }}</button></div><div v-if="availableImapFolders.length" class="folder-list"><label v-for="folder in availableImapFolders" :key="folder.name" class="folder-option" :class="{disabled:folder.flags.some(flag=>flag.toLowerCase()==='\\noselect')}"><input v-model="selectedImapFolders" type="checkbox" :value="folder.name" :disabled="folder.flags.some(flag=>flag.toLowerCase()==='\\noselect')"><span>{{ folder.name }}</span><small v-if="folder.flags.some(flag=>flag.toLowerCase()==='\\noselect')">分组</small></label></div><p v-else class="folder-empty">尚未读取文件夹。填写上方邮箱和授权码后，点击“读取文件夹”。</p><small class="folder-count">已选 {{ selectedImapFolders.length }} 个；最多 50 个。分组文件夹通常不可勾选，请选择其下实际存放邮件的子文件夹。</small></div>
    <div class="imap-security-note">授权码会先通过 IMAP 验证，然后用 AES-GCM 加密后保存到 D1。同步使用 BODY.PEEK 读取，不会修改远程已读状态。</div>
    <button class="button primary" :disabled="busy">{{ busy?'正在验证并保存…':'验证连接并保存' }}</button>
  </form>
</section><div v-if="!gmailSetup.configured&&!accounts.some(account=>account.connectionType==='forwarded_imap')" class="info-banner config-warning">Google OAuth 尚未配置。此页面的转发汇总邮箱可直接读取 QQ 邮箱中的已转发来源。Google OAuth 配置缺少：{{ gmailSetup.missingSecrets.join(', ') }}<br>授权回调地址：<code>{{ gmailSetup.redirectUri||'https://ear1.de5.net/oauth/gmail/callback' }}</code>。</div><section class="cards"><article v-for="account in accounts.filter(item=>item.connectionType!=='forwarded_imap')" :key="account.id" class="card account-card"><div class="card-head"><div class="provider-title"><span class="provider-icon">G</span><div><h3>Google Gmail</h3><small>官方 OAuth · 只读连接</small></div></div><span class="status-badge" :class="account.authStatus==='connected'?'active':'expired'">{{ account.authStatus==='connected'?'已连接':account.authStatus }}</span></div><div class="email-address">{{ account.emailAddress }}</div><div class="key-value"><span>同步状态</span><b>{{ account.syncStatus }}</b></div><div class="card-actions"><button class="button primary" :disabled="busy" @click="syncGmail(account)">立即同步</button></div></article><article v-if="!gmailSetup.configured" class="card outlook-card"><div class="card-head"><div class="provider-title"><span class="provider-icon outlook">＋</span><div><h3>更多邮箱服务</h3><small>Outlook、其他 IMAP 服务商</small></div></div><span class="status-badge">可扩展</span></div><p>可在接入相应服务接口后加入邮箱分类与来源列表。</p></article><article v-if="gmailSetup.configured&&!accounts.some(account=>account.connectionType!=='forwarded_imap')" class="card empty-card"><span class="provider-icon">G</span><h3>连接 Gmail</h3><p>也可通过官方 OAuth 将 Gmail 邮件直接同步。</p><button class="button primary" :disabled="busy" @click="connectGmail">连接账号</button></article></section></template>


      <template v-else><section class="page-title"><div><p class="eyebrow">PREFERENCES</p><h1>让工作台，配合你的节奏。</h1><p>这些偏好保存在当前浏览器，不会影响邮箱内容或 Cloudflare 数据。</p></div></section><div class="settings-grid"><form class="card settings-card" @submit.prevent="savePreferences"><h2>使用偏好</h2><label class="setting-row"><span><strong>默认邮箱有效期</strong><small>创建临时邮箱时使用的时长。</small></span><select v-model.number="preferences.ttl"><option :value="10">10 分钟</option><option :value="30">30 分钟</option><option :value="60">60 分钟</option><option :value="1440">24 小时</option></select></label><label class="setting-row"><span><strong>收件箱刷新间隔</strong><small>自动刷新邮件列表；手动点击“获取最新邮件”才会触发同步。</small></span><select v-model.number="preferences.refreshSeconds"><option :value="15">15 秒</option><option :value="20">20 秒</option><option :value="30">30 秒</option><option :value="60">60 秒</option></select></label><label class="setting-row"><span><strong>默认遮挡验证码</strong><small>打开邮件时先隐藏识别出的验证码。</small></span><input v-model="preferences.maskOtp" type="checkbox"></label><label class="setting-row"><span><strong>界面主题</strong><small>选择工作台的阅读主题。</small></span><select v-model="preferences.theme"><option value="light">浅色</option><option value="dark">深色</option></select></label><button class="button primary save-button" type="submit">保存设置</button></form><section class="card privacy-card"><h2>隐私与安全</h2><p>邮件内容与附件由 MailHub 服务端通过你的 Cloudflare 资源存储。</p><div class="key-value"><span>中转邮箱</span><b>只读访问</b></div><div class="key-value"><span>已读状态</span><b>MailHub 本地状态</b></div><div class="key-value"><span>邮件 HTML</span><b>隔离显示</b></div><div class="key-value"><span>附件病毒扫描</span><b>未提供</b></div></section></div></template>
    </main>
  </div>
</template>
